metrics.workdir_dsl:
workspace "Parcel Tracker" "A platform for tracking parcel deliveries" {
    !identifiers hierarchical

    model {
        properties {
            "structurizr.inspection.softwareSystem.documentation" "ignore"
            "structurizr.inspection.softwareSystem.decisions" "ignore"
        }

        customer = person "Customer" "Looks up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "A platform for tracking parcel deliveries, owned and operated by our company" {
            webPortal = container "Web Portal" "Where customers look up shipments" "Web application"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers" "Service"
            database = container "Database" "Stores shipments and dispatch records" "Relational database" "Database"
        }

        pricingLibrary = softwareSystem "Pricing Rules Library" "Computes delivery prices from weight and zone" "Library"
        emailProvider = softwareSystem "Email Delivery Provider" "Sends customer notification emails" "External"

        customer -> parcelTracker.webPortal "looks up the status of their parcels" "HTTPS"
        parcelTracker.webPortal -> parcelTracker.database "reads shipments from" "SQL"
        parcelTracker.dispatchService -> parcelTracker.database "writes dispatch records to" "SQL"
        parcelTracker.dispatchService -> emailProvider "sends customer notification emails through" "SMTP"
        parcelTracker.webPortal -> pricingLibrary "embeds" "compiled in"
        parcelTracker.dispatchService -> pricingLibrary "embeds" "compiled in"
    }

    configuration {
        scope softwaresystem
    }

    views {
        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Library" {
                background #6A737D
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
        }
    }
}
